def compute(vars):
    trading_assets = vars["v1"]
    trading_liabilities = vars["v2"]
    net_trading_assets = trading_assets - trading_liabilities

    return {
        "value": net_trading_assets,
        "trace": {
            "trading_assets_excluding_derivatives": trading_assets,
            "trading_liabilities_excluding_derivatives": trading_liabilities,
            "net_trading_assets": net_trading_assets,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
